// A RPC devolve UM objeto com a fila inteira. Aqui ele vira N itens, um por
// cliente, pro Loop Over Items poder paginar de 1 em 1.
const raw = $input.first().json;
const p = Array.isArray(raw) ? raw[0] : raw;

if (!p || !Array.isArray(p.pendentes)) {
  throw new Error('Payload inesperado de mapa_envios_pendentes: ' + JSON.stringify(raw).slice(0, 300));
}

// Fila vazia é o caso NORMAL (todo mundo já recebeu no mês, ou ninguém tem
// contato cadastrado). Retornar [] faz o loop não rodar e o workflow encerrar
// limpo — não é erro.
return p.pendentes.map((c) => ({
  json: { ...c, competencia: p.competencia, inelegiveis_cadastro: p.inelegiveis_cadastro },
}));

const p = $input.first().json;

// A competência vem do banco (já em America/Sao_Paulo). O 'T12:00:00' evita que
// o fuso do container jogue a data pro mês anterior na conversão.
const comp = new Date(p.competencia + 'T12:00:00');
const mesAno = comp.toLocaleDateString('pt-BR', { month: 'long', year: 'numeric' });

// nome_contato vem NULL quando o cadastro não tem contato. Sem isto a mensagem
// sairia "Olá, undefined!" — ou, pior, com um nome inventado pelo SQL.
const saudacao = p.nome_contato ? `Olá, ${p.nome_contato}! 👋` : 'Olá! 👋';

const mensagem = [
  saudacao,
  '',
  `O Mapa Tributário da ${p.empresa} referente a ${mesAno} está disponível:`,
  p.link,
  '',
  'Qualquer dúvida, é só responder por aqui.',
  '— Equipe Focus FinTax',
].join('\n');

return [{ json: { ...p, mensagem } }];

const p = $input.first().json;

function escapeHtml(s) {
  return String(s ?? '').replace(/[&<>"']/g, (c) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
  }[c]));
}

// Mesma lógica de mês/ano do Monta Mensagem, pra as duas mensagens sempre
// falarem do mesmo período mesmo se um cliente recebe os dois canais.
const comp = new Date(p.competencia + 'T12:00:00');
const mesAno = comp.toLocaleDateString('pt-BR', { month: 'long', year: 'numeric' });

const nome = escapeHtml(p.nome_contato);
const saudacao = p.nome_contato ? `Olá, ${nome}!` : 'Olá!';
const empresa = escapeHtml(p.empresa);
const link = escapeHtml(p.link);

const assunto = `Mapa Tributário — ${p.empresa} (${mesAno})`;

// Layout em tabela + CSS inline: é o único jeito que renderiza igual no
// Outlook/Gmail/Apple Mail. Paleta e tipografia batem com o app (navy #0a1564,
// vermelho #c8001e de CTA, fundo creme #f6f4ee, Barlow com fallback
// web-safe — cliente de e-mail não garante fonte customizada).
const html = `<!doctype html>
<html lang="pt-BR">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"></head>
<body style="margin:0;padding:0;background-color:#f6f4ee;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f6f4ee;">
<tr><td align="center" style="padding:32px 16px;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background-color:#ffffff;border-radius:20px;overflow:hidden;border:1px solid rgba(10,21,100,0.12);font-family:Barlow,Arial,Helvetica,sans-serif;">
<tr><td style="background-color:#0a1564;padding:20px 32px;">
<img src="https://focusfintax.com/images/logo-focus-fintax-white.png" alt="Focus FinTax" height="26" style="display:block;border:0;">
</td></tr>
<tr><td style="padding:32px;">
<p style="margin:0 0 16px;font-size:16px;line-height:1.5;color:#0f1117;">${saudacao} 👋</p>
<p style="margin:0 0 28px;font-size:16px;line-height:1.5;color:#0f1117;">O Mapa Tributário da <strong>${empresa}</strong> referente a <strong>${mesAno}</strong> está disponível para consulta.</p>
<table role="presentation" cellpadding="0" cellspacing="0"><tr><td style="border-radius:10px;background-color:#c8001e;">
<a href="${link}" style="display:inline-block;padding:14px 28px;font-size:15px;font-weight:600;color:#ffffff;text-decoration:none;border-radius:10px;font-family:Barlow,Arial,Helvetica,sans-serif;">Ver Mapa Tributário</a>
</td></tr></table>
<p style="margin:28px 0 0;font-size:13px;line-height:1.5;color:rgba(15,17,23,0.60);">Ou copie e cole este link no navegador:<br><a href="${link}" style="color:#0a1564;word-break:break-all;">${link}</a></p>
</td></tr>
<tr><td style="padding:20px 32px;border-top:1px solid rgba(10,21,100,0.10);background-color:#f6f4ee;">
<p style="margin:0;font-size:13px;line-height:1.5;color:rgba(15,17,23,0.60);">Qualquer dúvida, é só responder este e-mail.<br>— Equipe Focus FinTax</p>
</td></tr>
</table>
</td></tr>
</table>
</body>
</html>`;

return [{ json: { ...p, assunto, html } }];
